<?php
if(!defined('ABSPATH'))exit;
function legacyx_register_application_type(){register_post_type('legacyx_application',array('labels'=>array('name'=>'Applications','singular_name'=>'Application','menu_name'=>'Applications','add_new_item'=>'Add Application','edit_item'=>'Edit Application'),'public'=>false,'show_ui'=>true,'show_in_menu'=>true,'menu_icon'=>'dashicons-portfolio','supports'=>array('title'),'capability_type'=>'post','map_meta_cap'=>true,'show_in_rest'=>false));}add_action('init','legacyx_register_application_type');
function legacyx_application_boxes(){add_meta_box('legacyx_application_details','Application Details','legacyx_application_render_box','legacyx_application','normal','high');}add_action('add_meta_boxes','legacyx_application_boxes');
function legacyx_application_render_box($post){wp_nonce_field('legacyx_save_application','legacyx_application_nonce');$fields=array('client_id'=>'Universal Client Profile ID','type'=>'Application Type','status'=>'Status','requested_amount'=>'Requested Amount','provider'=>'Provider / Program','deadline'=>'Deadline','decision'=>'Decision / Outcome','required_documents'=>'Required Documents','advisor_note'=>'Advisor Note');$vals=array();foreach($fields as $k=>$l)$vals[$k]=get_post_meta($post->ID,'_legacyx_'.$k,true);echo '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">';foreach(array('client_id','type','status','requested_amount','provider','deadline','decision') as $k){echo '<p><label style="display:block;font-weight:600;margin-bottom:6px">'.esc_html($fields[$k]).'</label><input style="width:100%" name="legacyx_application['.esc_attr($k).']" value="'.esc_attr($vals[$k]).'"></p>';}echo '</div><p><label style="display:block;font-weight:600;margin-bottom:6px">Required Documents</label><textarea style="width:100%;min-height:80px" name="legacyx_application[required_documents]">'.esc_textarea($vals['required_documents']).'</textarea></p><p><label style="display:block;font-weight:600;margin-bottom:6px">Advisor Note</label><textarea style="width:100%;min-height:80px" name="legacyx_application[advisor_note]">'.esc_textarea($vals['advisor_note']).'</textarea></p>';}
function legacyx_application_save($id){if(get_post_type($id)!=='legacyx_application'||!isset($_POST['legacyx_application_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['legacyx_application_nonce'])),'legacyx_save_application')||!current_user_can('edit_post',$id)||!isset($_POST['legacyx_application'])||!is_array($_POST['legacyx_application']))return;$raw=wp_unslash($_POST['legacyx_application']);foreach(array('client_id','type','status','requested_amount','provider','deadline','decision') as $k)if(isset($raw[$k]))update_post_meta($id,'_legacyx_'.$k,sanitize_text_field($raw[$k]));foreach(array('required_documents','advisor_note') as $k)if(isset($raw[$k]))update_post_meta($id,'_legacyx_'.$k,sanitize_textarea_field($raw[$k]));}add_action('save_post_legacyx_application','legacyx_application_save');
function legacyx_get_client_applications($client_id){return get_posts(array('post_type'=>'legacyx_application','post_status'=>'publish','numberposts'=>-1,'meta_key'=>'_legacyx_client_id','meta_value'=>(string)absint($client_id),'orderby'=>'date','order'=>'DESC'));}
function legacyx_application_counts($client_id){$items=legacyx_get_client_applications($client_id);$out=array('active'=>0,'approved'=>0,'closed'=>0,'total'=>count($items));foreach($items as $item){$s=strtolower((string)get_post_meta($item->ID,'_legacyx_status',true));if(in_array($s,array('approved','funded','awarded'),true))$out['approved']++;elseif(in_array($s,array('closed','denied','withdrawn','completed'),true))$out['closed']++;else$out['active']++;}return $out;}
